mapper.select:
SELECT p.title AS title, COUNT(*) AS views
FROM product_view_log v
JOIN product p ON p.product_id = v.product_id
WHERE p.tenant_id = #{tenantId}
  AND v.view_time >= #{startTime} AND v.view_time < #{endTime}
GROUP BY p.product_id, p.title
ORDER BY views DESC
LIMIT #{limit}

SELECT LEFT(f.content, 50) AS summary, COUNT(*) AS likes
FROM feed_like l
JOIN feed f ON f.feed_id = l.feed_id
WHERE f.tenant_id = #{tenantId}
  AND l.create_time >= #{startTime} AND l.create_time < #{endTime}
GROUP BY f.feed_id, f.content
ORDER BY likes DESC
LIMIT #{limit}

select id, tenant_id, report_date, title, content, stats_json, source, create_time, update_time
from twelve_daily_report
where id = #{id} and tenant_id = #{tenantId}

select id, tenant_id, report_date, title, content, stats_json, source, create_time, update_time
from twelve_daily_report
where tenant_id = #{tenantId} and report_date = #{reportDate}
